import {
  ORB_FOCAL,
  ORB_FRAGMENT,
  ORB_INTRO_SECONDS,
  ORB_VERTEX,
} from './orb-shaders';
import type {
  OrbColor,
  OrbEngine,
  OrbEngineOptions,
  OrbProgram,
} from './types';

export const ORB_DEFAULT_COLORS = ['#9c43fe', '#4cc2e9', '#101499'];

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function compile(
  gl: WebGL2RenderingContext,
  type: number,
  source: string,
): WebGLShader | null {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (gl.getShaderParameter(shader, gl.COMPILE_STATUS)) return shader;
  gl.deleteShader(shader);
  return null;
}

function link(gl: WebGL2RenderingContext): OrbProgram | null {
  const vertex = compile(gl, gl.VERTEX_SHADER, ORB_VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, ORB_FRAGMENT);
  const program = gl.createProgram();
  if (!vertex || !fragment || !program) return null;
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.bindAttribLocation(program, 0, 'aPosition');
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program);
    return null;
  }
  const uniforms: Record<string, WebGLUniformLocation | null> = {};
  const count: number = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let i = 0; i < count; i++) {
    const info = gl.getActiveUniform(program, i);
    if (info) uniforms[info.name] = gl.getUniformLocation(program, info.name);
  }
  return { program, uniforms };
}

// Rotates a color around the luma axis in YIQ space, keeping brightness.
function shiftHue(rgb: OrbColor, degrees: number): OrbColor {
  if (!degrees) return rgb;
  const angle = (degrees * Math.PI) / 180;
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const [r, g, b] = rgb;
  const y = 0.299 * r + 0.587 * g + 0.114 * b;
  const i = 0.596 * r - 0.274 * g - 0.322 * b;
  const q = 0.211 * r - 0.523 * g + 0.312 * b;
  const ni = i * cos - q * sin;
  const nq = i * sin + q * cos;
  return [
    y + 0.956 * ni + 0.621 * nq,
    y - 0.272 * ni - 0.647 * nq,
    y - 1.106 * ni + 1.703 * nq,
  ];
}

export function createOrbEngine(options: OrbEngineOptions): OrbEngine | null {
  const { container, canvas, getSettings, reduce, onRestored } = options;
  const context = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
  });
  if (!context) return null;
  const gl: WebGL2RenderingContext = context;
  const linked = link(gl);
  if (!linked) return null;
  const program: OrbProgram = linked;
  const u = program.uniforms;

  function onContextLost(event: Event) {
    event.preventDefault();
  }
  canvas.addEventListener('webglcontextlost', onContextLost);
  canvas.addEventListener('webglcontextrestored', onRestored);

  const buffer = gl.createBuffer();
  const vao = gl.createVertexArray();
  gl.bindVertexArray(vao);
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
  gl.bufferData(
    gl.ARRAY_BUFFER,
    new Float32Array([-1, -1, 3, -1, -1, 3]),
    gl.STATIC_DRAW,
  );
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

  // Any CSS color string resolves through a 1×1 2D canvas.
  const probe = document
    .createElement('canvas')
    .getContext('2d', { willReadFrequently: true });
  const cache = new Map<string, OrbColor>();
  function parse(value: string): OrbColor {
    const hit = cache.get(value);
    if (hit) return hit;
    let rgb: OrbColor = [0, 0, 0];
    if (probe) {
      probe.clearRect(0, 0, 1, 1);
      probe.fillStyle = '#000000';
      probe.fillStyle = value;
      probe.fillRect(0, 0, 1, 1);
      const data = probe.getImageData(0, 0, 1, 1).data;
      rgb = data[3]
        ? [(data[0] ?? 0) / 255, (data[1] ?? 0) / 255, (data[2] ?? 0) / 255]
        : [0, 0, 0];
    }
    cache.set(value, rgb);
    return rgb;
  }

  const view = { width: 1, height: 1 };
  const pointer = { x: 0, y: 0, inside: false };
  const introOn = getSettings().intro && !reduce;
  const state = {
    time: 0,
    swirl: 0,
    orbit: 0,
    echo: 1,
    rotation: 0,
    hover: 0,
    near: 0,
    reachX: 0,
    reachY: 0,
    reachSpeedX: 0,
    reachSpeedY: 0,
    pulse: 0,
    pulseSpeed: 0,
    kick: introOn ? 2.5 : 0,
    reveal: introOn ? 0 : 1,
  };
  let raf = 0;
  let last = 0;
  let visible = true;
  let disposed = false;
  let lastDpr = getSettings().dpr;

  // Maps a container point into the orb's own (tilted, rotated) plane.
  function toOrb(x: number, y: number): [number, number] {
    const s = getSettings();
    const side = Math.min(view.width, view.height);
    const scale = 1 / (s.size * (1 + state.pulse));
    let ux = ((x - view.width / 2) / side) * 2 * scale;
    let uy = ((view.height / 2 - y) / side) * 2 * scale;
    if (s.tiltX || s.tiltY) {
      const ax = (-s.tiltX * Math.PI) / 180;
      const ay = (s.tiltY * Math.PI) / 180;
      const cx = Math.cos(ax);
      const sx = Math.sin(ax);
      const cy = Math.cos(ay);
      const sy = Math.sin(ay);
      const nx = sy * cx;
      const ny = -sx;
      const nz = cy * cx;
      const rx = ux;
      const ry = uy;
      const rz = -ORB_FOCAL;
      const denom = nx * rx + ny * ry + nz * rz;
      const t =
        -(nz * ORB_FOCAL) / (Math.abs(denom) > 0.00001 ? denom : -0.00001);
      if (t <= 0) return [99, 99];
      const qx = rx * t;
      const qy = ry * t;
      const qz = ORB_FOCAL + rz * t;
      ux = qx * cy - qz * sy;
      uy = qx * sy * sx + qy * cx + qz * cy * sx;
    }
    const sin = Math.sin(state.rotation);
    const cos = Math.cos(state.rotation);
    return [cos * ux - sin * uy, sin * ux + cos * uy];
  }

  function render() {
    const s = getSettings();
    const c1 = shiftHue(parse(s.colors[0]), s.hue);
    const c2 = shiftHue(parse(s.colors[1]), s.hue);
    const c3 = shiftHue(parse(s.colors[2]), s.hue);
    const reveal = state.reveal;
    const back = reveal - 1;
    const grow = 1 + 2.2 * back * back * back + 1.2 * back * back;
    const fade = Math.min(1, reveal / 0.55);
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.useProgram(program.program);
    gl.bindVertexArray(vao);
    gl.uniform2f(u.uResolution ?? null, canvas.width, canvas.height);
    gl.uniform1f(u.uTime ?? null, state.time);
    gl.uniform2f(u.uReach ?? null, state.reachX, state.reachY);
    gl.uniform1f(u.uNear ?? null, state.near);
    gl.uniform1f(u.uAwake ?? null, state.hover * s.hoverIntensity * 0.18);
    gl.uniform1f(u.uRotation ?? null, state.rotation);
    gl.uniform3fv(u.uBackground ?? null, parse(s.backgroundColor));
    gl.uniform3fv(u.uColor1 ?? null, c1);
    gl.uniform3fv(u.uColor2 ?? null, c2);
    gl.uniform3fv(u.uColor3 ?? null, c3);
    gl.uniform1f(
      u.uScale ?? null,
      1 / (s.size * (1 + state.pulse) * (0.62 + 0.38 * grow)),
    );
    gl.uniform1f(u.uWobble ?? null, s.wobble);
    gl.uniform1f(u.uGlow ?? null, s.glow);
    gl.uniform1f(u.uBleed ?? null, s.bleed);
    gl.uniform1f(u.uHighlight ?? null, s.highlight);
    gl.uniform2f(
      u.uEcho ?? null,
      state.echo * 0.55,
      state.echo < 1 ? (1 - state.echo) * (1 - state.echo) : 0,
    );
    gl.uniform1f(u.uSwirl ?? null, state.swirl);
    gl.uniform1f(u.uOrbit ?? null, state.orbit);
    gl.uniform1f(u.uReveal ?? null, fade * fade * (3 - 2 * fade));
    gl.uniform1f(u.uOpacity ?? null, s.opacity);
    gl.uniform1f(u.uTrail ?? null, s.trail);
    gl.uniform2f(
      u.uTilt ?? null,
      (-s.tiltX * Math.PI) / 180,
      (s.tiltY * Math.PI) / 180,
    );
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  }

  function frame(now: number) {
    raf = 0;
    if (disposed || !visible || document.hidden) return;
    const s = getSettings();
    const dt = last ? clamp((now - last) / 1000, 0.0005, 0.05) : 1 / 60;
    last = now;
    if (s.paused) {
      state.reveal = 1;
      render();
      last = 0;
      return;
    }
    const motion = reduce ? 0 : 1;
    const [px, py] = toOrb(pointer.x, pointer.y);
    const distance = Math.hypot(px, py);
    const region =
      pointer.inside && motion ? clamp((1.45 - distance) / 0.4, 0, 1) : 0;
    const zone = region * region * (3 - 2 * region);
    const aimed = zone * clamp((distance - 0.15) / 0.45, 0, 1);
    const near = zone > 0.5;
    const target = s.forceHoverState ? 1 : zone;
    state.hover += (target - state.hover) * (1 - Math.exp(-dt / 0.16));
    const reach = 0.075 * s.hoverIntensity * aimed;
    const goalX = distance > 0.0001 ? (px / distance) * reach : 0;
    const goalY = distance > 0.0001 ? (py / distance) * reach : 0;
    state.reachSpeedX +=
      (70 * (goalX - state.reachX) - 7 * state.reachSpeedX) * dt;
    state.reachSpeedY +=
      (70 * (goalY - state.reachY) - 7 * state.reachSpeedY) * dt;
    state.reachX += state.reachSpeedX * dt;
    state.reachY += state.reachSpeedY * dt;
    state.near +=
      (aimed * s.hoverIntensity - state.near) * (1 - Math.exp(-dt / 0.12));

    const step = dt * s.speed * motion;
    state.time += step;
    state.swirl += step * 2 * (1 + state.kick);
    state.echo = Math.min(1, state.echo + dt / 1.2);
    if (s.rotateOnHover) state.rotation += dt * 0.3 * state.hover * motion;

    const aim = Math.atan2(py, px);
    if (s.followCursor && near && motion) {
      const delta = Math.atan2(
        Math.sin(aim - state.orbit),
        Math.cos(aim - state.orbit),
      );
      state.orbit += delta * (1 - Math.exp(-dt * 6));
    } else {
      state.orbit -= step;
    }
    state.orbit = Math.atan2(Math.sin(state.orbit), Math.cos(state.orbit));

    state.pulseSpeed += (-170 * state.pulse - 11 * state.pulseSpeed) * dt;
    state.pulse += state.pulseSpeed * dt;
    state.kick *= Math.exp(-dt * 2.5);

    if (!s.intro || reduce) state.reveal = 1;
    else if (state.reveal < 1) {
      state.reveal = Math.min(1, state.reveal + dt / ORB_INTRO_SECONDS);
    }

    render();
    raf = requestAnimationFrame(frame);
  }

  function wake() {
    if (!raf && !disposed && visible && !document.hidden) {
      raf = requestAnimationFrame(frame);
    }
  }

  function resize() {
    if (disposed) return;
    const s = getSettings();
    const width = Math.max(1, container.clientWidth);
    const height = Math.max(1, container.clientHeight);
    const ratio = Math.min(s.dpr || window.devicePixelRatio || 1, 2);
    view.width = width;
    view.height = height;
    canvas.width = Math.max(1, Math.round(width * ratio));
    canvas.height = Math.max(1, Math.round(height * ratio));
    render();
    wake();
  }

  function locate(clientX: number, clientY: number) {
    const rect = container.getBoundingClientRect();
    pointer.x = clientX - rect.left;
    pointer.y = clientY - rect.top;
    pointer.inside =
      pointer.x >= 0 &&
      pointer.y >= 0 &&
      pointer.x <= rect.width &&
      pointer.y <= rect.height;
  }

  resize();

  return {
    refresh() {
      if (disposed) return;
      const s = getSettings();
      if (s.dpr !== lastDpr) {
        lastDpr = s.dpr;
        resize();
        return;
      }
      if (!raf) render();
      wake();
    },
    resize,
    pointerMove(clientX, clientY) {
      locate(clientX, clientY);
      if (!getSettings().paused) wake();
    },
    pointerDown(clientX, clientY) {
      const s = getSettings();
      locate(clientX, clientY);
      if (!pointer.inside || !s.clickPulse || s.paused || reduce) return;
      const [px, py] = toOrb(pointer.x, pointer.y);
      if (Math.hypot(px, py) > 1) return;
      state.pulseSpeed += 0.9;
      state.kick = 2.2;
      state.echo = 0;
      wake();
    },
    pointerUp(pointerType) {
      if (pointerType !== 'mouse') pointer.inside = false;
    },
    pointerLeave() {
      pointer.inside = false;
    },
    setVisible(next) {
      visible = next;
      if (visible) {
        last = 0;
        wake();
      }
    },
    visibilityChanged() {
      last = 0;
      wake();
    },
    dispose(loseContext) {
      disposed = true;
      cancelAnimationFrame(raf);
      raf = 0;
      canvas.removeEventListener('webglcontextlost', onContextLost);
      canvas.removeEventListener('webglcontextrestored', onRestored);
      gl.deleteProgram(program.program);
      gl.deleteBuffer(buffer);
      gl.deleteVertexArray(vao);
      if (loseContext) gl.getExtension('WEBGL_lose_context')?.loseContext();
    },
  };
}

export const ORB_INTRO_SECONDS = 1.1;
export const ORB_FOCAL = 3.2;

const FOCAL = ORB_FOCAL.toFixed(1);

export const ORB_VERTEX = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

export const ORB_FRAGMENT = `#version 300 es
precision highp float;
uniform vec2 uResolution;
uniform float uTime;
uniform float uRotation;
uniform vec2 uReach;
uniform float uNear;
uniform float uAwake;
uniform vec3 uBackground;
uniform vec3 uColor1;
uniform vec3 uColor2;
uniform vec3 uColor3;
uniform float uScale;
uniform float uWobble;
uniform float uGlow;
uniform float uBleed;
uniform float uHighlight;
uniform float uSwirl;
uniform float uOrbit;
uniform vec2 uEcho;
uniform float uReveal;
uniform float uOpacity;
uniform float uTrail;
uniform vec2 uTilt;
out vec4 outColor;

vec3 hash33(vec3 p3) {
  p3 = fract(p3 * vec3(0.1031, 0.11369, 0.13787));
  p3 += dot(p3, p3.yxz + 19.19);
  return -1.0 + 2.0 * fract(vec3(p3.x + p3.y, p3.x + p3.z, p3.y + p3.z) * p3.zyx);
}

float snoise3(vec3 p) {
  const float K1 = 0.333333333;
  const float K2 = 0.166666667;
  vec3 i = floor(p + (p.x + p.y + p.z) * K1);
  vec3 d0 = p - (i - (i.x + i.y + i.z) * K2);
  vec3 e = step(vec3(0.0), d0 - d0.yzx);
  vec3 i1 = e * (1.0 - e.zxy);
  vec3 i2 = 1.0 - e.zxy * (1.0 - e);
  vec3 d1 = d0 - (i1 - K2);
  vec3 d2 = d0 - (i2 - K1);
  vec3 d3 = d0 - 0.5;
  vec4 h = max(0.6 - vec4(dot(d0, d0), dot(d1, d1), dot(d2, d2), dot(d3, d3)), 0.0);
  vec4 n = h * h * h * h * vec4(dot(d0, hash33(i)), dot(d1, hash33(i + i1)), dot(d2, hash33(i + i2)), dot(d3, hash33(i + 1.0)));
  return dot(vec4(31.316), n);
}

float light1(float intensity, float attenuation, float dist) {
  return intensity / (1.0 + dist * attenuation);
}

float light2(float intensity, float attenuation, float dist) {
  return intensity / (1.0 + dist * dist * attenuation);
}

vec4 draw(vec2 uv) {
  float rawLen = length(uv);
  vec2 dir = rawLen > 0.0001 ? uv / rawLen : vec2(1.0, 0.0);
  float reachAmount = length(uReach);
  vec2 reachDir = reachAmount > 0.00001 ? uReach / reachAmount : vec2(1.0, 0.0);
  float facing = exp((dot(dir, reachDir) - 1.0) * 3.2);
  float len = max(rawLen - reachAmount * facing * smoothstep(0.25, 0.65, rawLen), 0.0);
  uv = dir * len;
  float ang = atan(dir.y, dir.x);
  float invLen = len > 0.0 ? 1.0 / len : 0.0;
  float near = facing * uNear;
  float bgLuminance = dot(uBackground, vec3(0.299, 0.587, 0.114));

  float n0 = snoise3(vec3(uv * 0.65, uTime * 0.5)) * 0.5 + 0.5;
  float r0 = mix(0.8 - 0.04 * uWobble, 0.8 + 0.04 * uWobble, n0);
  float d0 = distance(uv, (r0 * invLen) * uv);
  float v0 = light1(1.0, 10.0 / uGlow, d0);
  v0 *= smoothstep(r0 * 1.05, r0, len);
  float reach = max(uBleed, 0.04);
  float innerFade = smoothstep(r0 * (1.0 - 0.2 * reach), r0 * (1.0 - 0.05 * reach), len);
  v0 *= mix(innerFade, 1.0, bgLuminance * 0.7 * min(uBleed, 1.0));
  float body = smoothstep(0.8 - 0.2 * reach, 0.8, len);
  float cl = cos(ang + uSwirl) * 0.5 + 0.5;

  vec2 pos = vec2(cos(uOrbit), sin(uOrbit)) * r0;
  float d = distance(uv, pos);
  vec2 head = vec2(cos(uOrbit), sin(uOrbit));
  float lag = atan(head.x * dir.y - head.y * dir.x, dot(dir, head));
  float trail = uTrail > 0.0 ? smoothstep(0.0, 0.35, lag) * exp(-max(lag, 0.0) * 2.6 / uTrail) : 0.0;
  float v1 = (light2(1.5, 5.0, d) + trail * 0.6) * uHighlight;
  v1 *= light1(1.0, 50.0, d0);
  float band = v0 * smoothstep(1.0, mix(0.6, 1.0, n0 * 0.5), len) * body;
  float heat = pow(clamp(band / 0.82, 0.0, 1.0), 3.0);
  float bloom = light2(1.0, 160.0 / uGlow, max(len - r0, 0.0)) * smoothstep(0.4, 0.0, len - r0) * step(r0, len);

  float v2 = smoothstep(1.0, mix(0.6, 1.0, n0 * 0.5), len);
  float v3 = body;

  vec3 colBase = mix(uColor1, uColor2, cl);
  float fadeAmount = mix(1.0, 0.1, bgLuminance);

  float echoD = abs(len - r0 - uEcho.x);
  float echo = light1(1.0, 60.0, echoD) * smoothstep(0.12, 0.0, echoD) * uEcho.y;

  vec3 darkCol = mix(uColor3, colBase, v0);
  darkCol = (darkCol + v1) * v2 * v3 * (1.0 + uAwake + near * 0.35) + mix(colBase, vec3(1.0), 0.25) * heat * (0.28 + near * 0.3);
  darkCol = clamp(darkCol + colBase * (bloom * 0.1 + echo), 0.0, 1.0);

  vec3 lightCol = (colBase + v1) * mix(1.0, v2 * v3, fadeAmount);
  lightCol = mix(uBackground, lightCol, clamp(v0 + echo, 0.0, 1.0));
  lightCol = mix(lightCol, colBase, clamp(v0, 0.0, 1.0) * clamp(near * 0.4 + uAwake, 0.0, 0.6));
  lightCol = clamp(mix(lightCol, vec3(1.0), clamp(v1 * 0.35, 0.0, 0.6)), 0.0, 1.0);

  vec3 finalCol = mix(darkCol, lightCol, bgLuminance);
  float alpha = max(max(finalCol.r, finalCol.g), finalCol.b);
  return vec4(finalCol / (alpha + 1e-5), alpha);
}

vec2 toPlane(vec2 p, out float hit) {
  float cx = cos(uTilt.x);
  float sx = sin(uTilt.x);
  float cy = cos(uTilt.y);
  float sy = sin(uTilt.y);
  vec3 ex = vec3(cy, 0.0, -sy);
  vec3 ey = vec3(sy * sx, cx, cy * sx);
  vec3 normal = vec3(sy * cx, -sx, cy * cx);
  vec3 origin = vec3(0.0, 0.0, ${FOCAL});
  vec3 ray = vec3(p, -${FOCAL});
  float denom = dot(normal, ray);
  float t = -dot(normal, origin) / (abs(denom) > 0.00001 ? denom : -0.00001);
  hit = t > 0.0 ? 1.0 : 0.0;
  vec3 q = origin + ray * t;
  return vec2(dot(q, ex), dot(q, ey));
}

void main() {
  vec2 uv = (gl_FragCoord.xy - uResolution * 0.5) / min(uResolution.x, uResolution.y) * 2.0;
  uv *= uScale;
  float hit = 1.0;
  if (abs(uTilt.x) + abs(uTilt.y) > 0.0001) uv = toPlane(uv, hit);

  float s = sin(uRotation);
  float c = cos(uRotation);
  uv = vec2(c * uv.x - s * uv.y, s * uv.x + c * uv.y);

  vec4 col = draw(uv);
  float dither = (fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453) - 0.5) / 255.0;
  float alpha = clamp(col.a * hit * uReveal * uOpacity + dither, 0.0, 1.0);
  outColor = vec4(col.rgb * alpha * alpha, alpha);
}`;

export type OrbColor = [number, number, number];

export interface OrbProps {
  /** Two colors that swirl around the ring, then the deep glow color. */
  colors?: string[];
  /** Shifts the hue of every color, in degrees. */
  hue?: number;
  /** Color the orb sits on. Light colors switch it to a filled style. */
  backgroundColor?: string;
  /** Size of the orb relative to the container. */
  size?: number;
  /** How soft and wide the glow around the ring is. */
  glow?: number;
  /** How far the glow bleeds into the inside of the orb. */
  bleed?: number;
  /** How much the ring breathes and warps at rest. */
  wobble?: number;
  /** Brightness of the light that orbits the ring. */
  highlight?: number;
  /** Length of the tail behind the orbiting light. */
  trail?: number;
  /** Tilts the ring back in perspective, in degrees. */
  tiltX?: number;
  /** Turns the ring sideways in perspective, in degrees. */
  tiltY?: number;
  /** Speed of the swirl, the orbiting light and the breathing. */
  speed?: number;
  /** How far the ring reaches toward the cursor and how bright it gets. */
  hoverIntensity?: number;
  /** Slowly turns the orb while it is hovered. */
  rotateOnHover?: boolean;
  /** Keeps the hover effect on without hovering. */
  forceHoverState?: boolean;
  /** The orbiting light swings toward the cursor while hovered. */
  followCursor?: boolean;
  /** Clicking the orb makes it pulse and swirl. */
  clickPulse?: boolean;
  /** Powers the orb on with a spring and a swirl. */
  intro?: boolean;
  /** Opacity of the whole effect. */
  opacity?: number;
  /** Freezes the animation. */
  paused?: boolean;
